    "inlineSchema": "// Prisma schema: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  ADMIN\n  USER\n}\n\nenum UserStatus {\n  CANDIDATE\n  DIPLOMATE\n}\n\nenum CertificationStatus {\n  ACTIVE\n  LAPSED\n}\n\nenum FieldType {\n  TEXT\n  LONG_TEXT\n  NUMBER\n  DATE\n  DROPDOWN\n  CHECKBOX\n  FILE\n}\n\nenum EmailTokenType {\n  VERIFY\n  RESET\n}\n\nmodel User {\n  id              String     @id @default(uuid())\n  email           String     @unique\n  passwordHash    String     @map(\"password_hash\")\n  role            Role       @default(USER)\n  name            String\n  status          UserStatus @default(CANDIDATE)\n  emailVerifiedAt DateTime?  @map(\"email_verified_at\")\n  onboardedAt     DateTime?  @map(\"onboarded_at\")\n\n  // Cached values, always rebuildable from certification records (sync service).\n  cycleStartDate   DateTime? @map(\"cycle_start_date\")\n  cycleNo          Int       @default(0) @map(\"cycle_no\")\n  progressCount    Int       @default(0) @map(\"progress_count\")\n  atRisk           Boolean   @default(false) @map(\"at_risk\")\n  warningSentCycle Int?      @map(\"warning_sent_cycle\")\n\n  // Denormalised copies of profile/certification values for search and sort.\n  passportNo String? @map(\"passport_no\")\n  lastCertNo String? @map(\"last_cert_no\")\n\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  emailTokens    EmailToken[]\n  profileAnswers ProfileAnswer[]\n  certifications Certification[]\n  files          StoredFile[]\n\n  @@index([status])\n  @@index([deletedAt])\n  @@map(\"users\")\n}\n\nmodel EmailToken {\n  id        String         @id @default(uuid())\n  userId    String         @map(\"user_id\")\n  type      EmailTokenType\n  tokenHash String         @unique @map(\"token_hash\")\n  expiresAt DateTime       @map(\"expires_at\")\n  usedAt    DateTime?      @map(\"used_at\")\n  createdAt DateTime       @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, type])\n  @@map(\"email_tokens\")\n}\n\nmodel Step {\n  id         String   @id @default(uuid())\n  key        String   @unique\n  title      String\n  order      Int\n  enabled    Boolean  @default(true)\n  system     Boolean  @default(false)\n  // Profile steps are filled once; the certification step is repeatable.\n  repeatable Boolean  @default(false)\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  fields Field[]\n\n  @@map(\"steps\")\n}\n\nmodel Field {\n  id         String    @id @default(uuid())\n  stepId     String    @map(\"step_id\")\n  key        String\n  label      String\n  type       FieldType\n  required   Boolean   @default(false)\n  helpText   String?   @map(\"help_text\")\n  visible    Boolean   @default(true)\n  options    Json?\n  order      Int\n  system     Boolean   @default(false)\n  archivedAt DateTime? @map(\"archived_at\")\n  createdAt  DateTime  @default(now()) @map(\"created_at\")\n  updatedAt  DateTime  @updatedAt @map(\"updated_at\")\n\n  step    Step            @relation(fields: [stepId], references: [id], onDelete: Cascade)\n  answers ProfileAnswer[]\n\n  @@unique([stepId, key])\n  @@map(\"fields\")\n}\n\nmodel ProfileAnswer {\n  userId    String   @map(\"user_id\")\n  fieldId   String   @map(\"field_id\")\n  value     Json\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  field Field @relation(fields: [fieldId], references: [id], onDelete: Cascade)\n\n  @@id([userId, fieldId])\n  @@map(\"profile_answers\")\n}\n\nmodel Certification {\n  id         String              @id @default(uuid())\n  userId     String              @map(\"user_id\")\n  cycleNo    Int                 @map(\"cycle_no\")\n  data       Json\n  fileId     String?             @map(\"file_id\")\n  status     CertificationStatus @default(ACTIVE)\n  uploadedAt DateTime            @map(\"uploaded_at\") // immutable, server time\n  lapsedAt   DateTime?           @map(\"lapsed_at\")\n  createdAt  DateTime            @default(now()) @map(\"created_at\")\n  updatedAt  DateTime            @updatedAt @map(\"updated_at\")\n  deletedAt  DateTime?           @map(\"deleted_at\")\n\n  user User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  file StoredFile? @relation(fields: [fileId], references: [id])\n\n  @@index([userId, status])\n  @@index([userId, cycleNo])\n  @@map(\"certifications\")\n}\n\nmodel StoredFile {\n  id           String   @id @default(uuid())\n  ownerId      String   @map(\"owner_id\")\n  storedName   String   @unique @map(\"stored_name\")\n  originalName String   @map(\"original_name\")\n  mime         String\n  size         Int\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  owner          User            @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  certifications Certification[]\n\n  @@map(\"files\")\n}\n\nmodel Setting {\n  key       String   @id\n  value     Json\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"settings\")\n}\n\nmodel AuditLog {\n  id        String   @id @default(uuid())\n  actorId   String?  @map(\"actor_id\")\n  action    String\n  entity    String\n  entityId  String?  @map(\"entity_id\")\n  before    Json?\n  after     Json?\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@index([entity, entityId])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n",
